import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  alertDialogActionsClasses,
  alertDialogBackdropClasses,
  alertDialogCancelClasses,
  alertDialogConfirmClasses,
  alertDialogDescriptionClasses,
  alertDialogPopupClasses,
  alertDialogPortalClasses,
  alertDialogRootClasses,
  alertDialogTitleClasses,
  alertDialogTriggerClasses,
  alertDialogViewportClasses,
} from "./view";

export {
  alertDialogActionsClasses,
  alertDialogBackdropClasses,
  alertDialogCancelClasses,
  alertDialogConfirmClasses,
  alertDialogDescriptionClasses,
  alertDialogPopupClasses,
  alertDialogPortalClasses,
  alertDialogRootClasses,
  alertDialogTitleClasses,
  alertDialogTriggerClasses,
  alertDialogViewportClasses,
} from "./view";

export type AlertDialogStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
  style?: AlertDialogStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  onClick: ParentMessage;
  children: readonly Html[];
  className?: string | undefined;
  style?: AlertDialogStyle | undefined;
}>;

export type PortalViewConfig = Readonly<{
  open: boolean;
  children: readonly Html[];
  className?: string | undefined;
  style?: AlertDialogStyle | undefined;
}>;

export type PartViewConfig = Readonly<{
  id?: string | undefined;
  children: readonly Html[];
  className?: string | undefined;
  style?: AlertDialogStyle | undefined;
}>;

export type PopupViewConfig = Readonly<{
  titleId: string;
  descriptionId: string;
  children: readonly Html[];
  className?: string | undefined;
  style?: AlertDialogStyle | undefined;
}>;

export type CloseViewConfig<ParentMessage> = Readonly<{
  onClick: ParentMessage;
  children: readonly Html[];
  variant?: "Cancel" | "Confirm" | undefined;
  className?: string | undefined;
  style?: AlertDialogStyle | undefined;
}>;

const cn = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const partView = <ParentMessage>(
  tagName: "div" | "h2" | "p",
  baseClasses: string,
  { id, children, className, style }: PartViewConfig
): Html => {
  const h = html<ParentMessage>();
  const attributes = [
    ...(id === undefined ? [] : [h.Id(id)]),
    ...(style === undefined ? [] : [h.Style(style)]),
    h.Class(cn(baseClasses, className)),
  ];

  if (tagName === "h2") {
    return h.h2(attributes, children);
  }

  if (tagName === "p") {
    return h.p(attributes, children);
  }

  return h.div(attributes, children);
};

export const rootView = <ParentMessage>({
  children,
  className,
  style,
}: RootViewConfig): Html =>
  partView<ParentMessage>("div", alertDialogRootClasses, {
    children,
    className,
    style,
  });

export const triggerView = <ParentMessage>({
  onClick,
  children,
  className,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.OnClick(onClick),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(alertDialogTriggerClasses, className)),
    ],
    children
  );
};

export const portalView = <ParentMessage>({
  open,
  children,
  className,
  style,
}: PortalViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.div([h.Hidden(true)], []);
  }

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(alertDialogPortalClasses, className)),
    ],
    children
  );
};

export const backdropView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("div", alertDialogBackdropClasses, config);

export const viewportView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("div", alertDialogViewportClasses, config);

export const popupView = <ParentMessage>({
  titleId,
  descriptionId,
  children,
  className,
  style,
}: PopupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "alertdialog"),
      h.Attribute("aria-modal", "true"),
      h.Attribute("aria-labelledby", titleId),
      h.Attribute("aria-describedby", descriptionId),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(alertDialogPopupClasses, className)),
    ],
    children
  );
};

export const titleView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("h2", alertDialogTitleClasses, config);

export const descriptionView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("p", alertDialogDescriptionClasses, config);

export const actionsView = <ParentMessage>(config: PartViewConfig): Html =>
  partView<ParentMessage>("div", alertDialogActionsClasses, config);

export const closeView = <ParentMessage>({
  onClick,
  children,
  variant = "Cancel",
  className,
  style,
}: CloseViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();
  const baseClasses =
    variant === "Confirm"
      ? alertDialogConfirmClasses
      : alertDialogCancelClasses;

  return h.button(
    [
      h.Type("button"),
      h.OnClick(onClick),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(baseClasses, className)),
    ],
    children
  );
};

export const alertDialogRootClasses = "contents";

export const alertDialogTriggerClasses =
  "inline-flex h-10 w-fit items-center justify-center rounded-md bg-gray-950 px-4 text-sm font-medium text-white transition-colors hover:bg-gray-800";

export const alertDialogPortalClasses = "fixed inset-0 z-50";

export const alertDialogBackdropClasses = "fixed inset-0 bg-black/30";

export const alertDialogViewportClasses =
  "fixed inset-0 grid place-items-center p-4";

export const alertDialogPopupClasses =
  "grid w-full max-w-sm gap-4 rounded-lg bg-white p-6 shadow-xl";

export const alertDialogTitleClasses = "text-lg font-semibold text-gray-950";

export const alertDialogDescriptionClasses = "text-sm text-gray-600";

export const alertDialogActionsClasses = "flex justify-end gap-2";

export const alertDialogCancelClasses =
  "inline-flex h-9 items-center justify-center rounded-md border border-gray-300 bg-white px-3 text-sm font-medium text-gray-900 hover:bg-gray-50";

export const alertDialogConfirmClasses =
  "inline-flex h-9 items-center justify-center rounded-md bg-red-600 px-3 text-sm font-medium text-white hover:bg-red-700";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as AlertDialog from ".";

const view = (open: boolean) => {
  const h = html<boolean>();

  return AlertDialog.rootView<boolean>({
    children: [
      AlertDialog.triggerView({
        onClick: true,
        children: [h.span([], ["Discard draft"])],
      }),
      AlertDialog.portalView({
        open,
        children: [
          AlertDialog.backdropView({ children: [] }),
          AlertDialog.viewportView({
            children: [
              AlertDialog.popupView({
                titleId: "title",
                descriptionId: "description",
                children: [
                  AlertDialog.titleView({
                    id: "title",
                    children: [h.span([], ["Discard draft?"])],
                  }),
                  AlertDialog.descriptionView({
                    id: "description",
                    children: [h.span([], ["You can't undo this action."])],
                  }),
                ],
              }),
            ],
          }),
        ],
      }),
    ],
  });
};

describe("AlertDialog registry component", () => {
  test("opens an aria-labelled alert dialog", () => {
    Scene.scene(
      {
        update: (_model: boolean, message: boolean) => [message, []] as const,
        view,
      },
      Scene.with(false),
      Scene.expect(
        Scene.role("alertdialog", { name: "Discard draft?" })
      ).not.toExist(),
      Scene.click(Scene.role("button", { name: "Discard draft" })),
      Scene.expect(
        Scene.role("alertdialog", { name: "Discard draft?" })
      ).toHaveAttr("aria-describedby", "description")
    );
  });

  test("exports Base UI alert dialog class hooks", () => {
    expect(AlertDialog.alertDialogPopupClasses).toContain("shadow");
    expect(AlertDialog.alertDialogConfirmClasses).toContain("red");
  });
});
